Method.Implementation:
	    // ^TELCORBILLINGCOUNTER(SourceSystem,Date) - Contains total transaction sent to telcor operation
	    // ^TELCORBILLINGSENDCOUNTER(SourceSystem,Date) - Contains count of transaction sent successfuly by Telcor TCP operation to Telcor
        #dim tSC As %Status = $$$OK
		// Get current Date 
		$$$TRACE("Inside OnProcessInput...")
		set priorDate=$SYSTEM.SQL.DATEADD("DD",-1,$H)
		set priorDateH=$ZDATEH($p(priorDate," "),3)
		set forDate=$ZDATE(priorDateH,8)
		// If report processed for prior day then quit without further action. Else look at the Globals
		if ('$data(^TELCORBILLINGREPORT(..%ConfigName,forDate))){
			$$$TRACE("Processing For Date "_forDate)
			// Kill the old status global
			k ^TELCORBILLINGREPORT(..%ConfigName)
			// Check if the data present in the counter if data is present means the billing records were present otherwise No billing
			// records received for Telcor from the source system
			If ($data(^TELCORBILLINGCOUNTER(..SourceSystem,forDate))){
				set wOutstandingCount=^TELCORBILLINGCOUNTER(..SourceSystem,forDate)-$g(^TELCORBILLINGSENDCOUNTER(..SourceSystem,forDate),0)
				$$$TRACE("Outstanding counts For Date "_forDate_" are "_wOutstandingCount)
				If (wOutstandingCount=0){
					set wSubject=..SuccessEmailSubject
					set wBody=..SucessEmailBody
					set wSubject=$REPLACE(wSubject,"#OUTSTANDINGCOUNT",wOutstandingCount)
					set wSubject=$REPLACE(wSubject,"#FORDATE",forDate)
					set wBody=$REPLACE(wBody,"#OUTSTANDINGCOUNT",wOutstandingCount)
					set wBody=$REPLACE(wBody,"#FORDATE",forDate)
					do ..ItfSendEmailOnSuccess(wSubject,wBody)
				}Else{
					set wSubject=..FailureEmailSubject
					set wBody=..FailureEmailBody
					set wSubject=$REPLACE(wSubject,"#OUTSTANDINGCOUNT",wOutstandingCount)
					set wSubject=$REPLACE(wSubject,"#FORDATE",forDate)
					set wBody=$REPLACE(wBody,"#OUTSTANDINGCOUNT",wOutstandingCount)
					set wBody=$REPLACE(wBody,"#FORDATE",forDate)
					do ..ItfSendEmailOnError(wSubject,wBody)
				}
			}Else{
				$$$TRACE("No Billing records found For Date "_forDate)
				set tSC=##class(IHC.ITF.ITFCOMMON.Utility).FailMsgError(..%ConfigName,"No Billing transaction processed for date "_forDate_".Kindly check with the source system.")
			}
			set ^TELCORBILLINGREPORT(..%ConfigName,forDate)=1

		}

		quit tSC
